window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-92a7d261e0d94e65"]={"versions": [{"id": "FIG-92a7d261e0d94e65", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC) im Kontext des Diagnostic Event Manager (<code>Dem</code>). Das Diagramm definiert die Konfigurationscontainer und -parameter für Benachrichtigungs-Callbacks bei Statusänderungen von Diagnostic Trouble Codes (DTC) für Standard-, OBD- und J1939-Kontexte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm gliedert sich ausgehend vom Hauptcontainer <code>DemGeneral</code> (Instanz von <code>EcucParamConfContainerDef</code>, Multiplizität 1..1) in drei Pfade mit Subcontainern und Funktionsnamen-Parametern:</p>\n<ul class=\"fig-list\">\n<li>Standard-DTC-Statuswechsel:</li>\n<li><code>DemGeneral</code> aggregiert über die Rolle <code>+subContainer</code> den Container <code>DemCallbackDTCStatusChanged : EcucParamConfContainerDef</code> (Multiplizität 0..\\*).</li>\n<li><code>DemCallbackDTCStatusChanged</code> enthält über die Rolle <code>+parameter</code> den Konfigurationsparameter <code>DemCallbackDTCStatusChangedFnc : EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>OBD-spezifischer DTC-Statuswechsel:</li>\n<li><code>DemGeneral</code> aggregiert über <code>+subContainer</code> den optionalen Container <code>DemGeneralOBD : EcucParamConfContainerDef</code> (Multiplizität 0..1).</li>\n<li><code>DemGeneralOBD</code> aggregiert über <code>+subContainer</code> den Container <code>DemCallbackOBDDTCStatusChanged : EcucParamConfContainerDef</code> (Multiplizität 0..\\*).</li>\n<li><code>DemCallbackOBDDTCStatusChanged</code> enthält über <code>+parameter</code> den Parameter <code>DemCallbackDTCStatusChangedFnc : EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>J1939-spezifischer DTC-Statuswechsel:</li>\n<li><code>DemGeneral</code> aggregiert über <code>+subContainer</code> den optionalen Container <code>DemGeneralJ1939 : EcucParamConfContainerDef</code> (Multiplizität 0..1).</li>\n<li><code>DemGeneralJ1939</code> aggregiert über <code>+subContainer</code> den Container <code>DemCallbackJ1939DTCStatusChanged : EcucParamConfContainerDef</code> (Multiplizität 0..\\*).</li>\n<li><code>DemCallbackJ1939DTCStatusChanged</code> enthält über <code>+parameter</code> den Parameter <code>DemCallbackDTCStatusChangedFnc : EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell bildet das Diagramm selbst keine Laufzeit-Sequenzen ab. Es spezifiziert die statische Konfiguration von Callback-Funktionen: Ändert sich zur Laufzeit der Status eines DTC (allgemein, OBD- oder J1939-bezogen), ruft das Dem-Modul die über den C-Funktionsbezeichner <code>DemCallbackDTCStatusChangedFnc</code> konfigurierten Benachrichtigungsfunktionen auf. Da die Callback-Container eine obere Multiplizität von <code>*</code> besitzen, können je Domäne mehrere Callback-Funktionen registriert werden, die bei Statusänderungen sequenziell oder ereignisbezogen benachrichtigt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfigurationsparameter sind normativ für die Generierung und Konfiguration des Dem-Moduls im BSW-Stack. Fehlt die Definition eines Funktionsnamens (<code>lowerMultiplicity = 0</code>), wird kein entsprechender Callback registriert. Entwickler müssen sicherstellen, dass die als <code>EcucFunctionNameDef</code> eingetragenen C-Symbole der Signatur des AUTOSAR Dem-DTC-Statuswechsel-Callbacks entsprechen und linkbar bzw. im RTE/BSW-Umfeld deklariert sind. Die Unterstützung für OBD- und J1939-Callbacks ist optional und hängt vom Vorhandensein der jeweiligen Subcontainer <code>DemGeneralOBD</code> bzw. <code>DemGeneralJ1939</code> ab.</p>"}, {"id": "FIG-eaaea11049be0a31", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC) im Kontext des Diagnostic Event Manager (<code>Dem</code>). Das Diagramm definiert die Konfigurationscontainer und -parameter für Benachrichtigungs-Callbacks bei Statusänderungen von Diagnostic Trouble Codes (DTC) für Standard-, OBD- und J1939-Kontexte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm gliedert sich ausgehend vom Hauptcontainer <code>DemGeneral</code> (Instanz von <code>EcucParamConfContainerDef</code>, Multiplizität 1..1) in drei Pfade mit Subcontainern und Funktionsnamen-Parametern:</p>\n<ul class=\"fig-list\">\n<li>Standard-DTC-Statuswechsel:</li>\n<li><code>DemGeneral</code> aggregiert über die Rolle <code>+subContainer</code> den Container <code>DemCallbackDTCStatusChanged : EcucParamConfContainerDef</code> (Multiplizität 0..\\*).</li>\n<li><code>DemCallbackDTCStatusChanged</code> enthält über die Rolle <code>+parameter</code> den Konfigurationsparameter <code>DemCallbackDTCStatusChangedFnc : EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>OBD-spezifischer DTC-Statuswechsel:</li>\n<li><code>DemGeneral</code> aggregiert über <code>+subContainer</code> den optionalen Container <code>DemGeneralOBD : EcucParamConfContainerDef</code> (Multiplizität 0..1).</li>\n<li><code>DemGeneralOBD</code> aggregiert über <code>+subContainer</code> den Container <code>DemCallbackOBDDTCStatusChanged : EcucParamConfContainerDef</code> (Multiplizität 0..\\*).</li>\n<li><code>DemCallbackOBDDTCStatusChanged</code> enthält über <code>+parameter</code> den Parameter <code>DemCallbackDTCStatusChangedFnc : EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n</ul>\n<ul class=\"fig-list\">\n<li>J1939-spezifischer DTC-Statuswechsel:</li>\n<li><code>DemGeneral</code> aggregiert über <code>+subContainer</code> den optionalen Container <code>DemGeneralJ1939 : EcucParamConfContainerDef</code> (Multiplizität 0..1).</li>\n<li><code>DemGeneralJ1939</code> aggregiert über <code>+subContainer</code> den Container <code>DemCallbackJ1939DTCStatusChanged : EcucParamConfContainerDef</code> (Multiplizität 0..\\*).</li>\n<li><code>DemCallbackJ1939DTCStatusChanged</code> enthält über <code>+parameter</code> den Parameter <code>DemCallbackDTCStatusChangedFnc : EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell bildet das Diagramm selbst keine Laufzeit-Sequenzen ab. Es spezifiziert die statische Konfiguration von Callback-Funktionen: Ändert sich zur Laufzeit der Status eines DTC (allgemein, OBD- oder J1939-bezogen), ruft das Dem-Modul die über den C-Funktionsbezeichner <code>DemCallbackDTCStatusChangedFnc</code> konfigurierten Benachrichtigungsfunktionen auf. Da die Callback-Container eine obere Multiplizität von <code>*</code> besitzen, können je Domäne mehrere Callback-Funktionen registriert werden, die bei Statusänderungen sequenziell oder ereignisbezogen benachrichtigt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfigurationsparameter sind normativ für die Generierung und Konfiguration des Dem-Moduls im BSW-Stack. Fehlt die Definition eines Funktionsnamens (<code>lowerMultiplicity = 0</code>), wird kein entsprechender Callback registriert. Entwickler müssen sicherstellen, dass die als <code>EcucFunctionNameDef</code> eingetragenen C-Symbole der Signatur des AUTOSAR Dem-DTC-Statuswechsel-Callbacks entsprechen und linkbar bzw. im RTE/BSW-Umfeld deklariert sind. Die Unterstützung für OBD- und J1939-Callbacks ist optional und hängt vom Vorhandensein der jeweiligen Subcontainer <code>DemGeneralOBD</code> bzw. <code>DemGeneralJ1939</code> ab.</p>"}], "trans": [{"from": "FIG-92a7d261e0d94e65", "to": "FIG-eaaea11049be0a31", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
